function entry(id, year, title, category, sourcePages, pl, uk, originalUk, notePl = '', note = '') {
  return {
    id: `document-${id}`,
    year,
    title,
    pl,
    uk,
    original: originals[`document-${id}`],
    originalUk,
    note,
    notePl,
    date: '',
    source,
    category,
    sourcePages,
  };
}

